function write_reproducibility_manifest(cfg,bench,mc)
%WRITE_REPRODUCIBILITY_MANIFEST Records exact experiment settings.
fid=fopen(fullfile(cfg.outputDir,'REPRODUCIBILITY_MANIFEST.txt'),'w');
fprintf(fid,'RESEARCH-READY DRIFT CONTROL REPRODUCIBILITY MANIFEST\n');fprintf(fid,'================================================\n');fprintf(fid,'Random seed: %d\nResearch dt: %.8g s\nResearch duration: %.8g s\nMonte Carlo dt: %.8g s\nMonte Carlo cases/controller: %d\n',cfg.randomSeed,cfg.researchDt,cfg.researchT,cfg.monteCarloDt,cfg.paperMonteCarloRuns);fprintf(fid,'Common command-rate limits: %d\nSteering rate: %.6f deg/s\nThrottle rate: %.6f 1/s\n',cfg.enforceCommonCommandRateLimits,rad2deg(cfg.mpcSteerRate),cfg.mpcThrottleRate);fprintf(fid,'Controllers: ');for i=1:numel(bench.labels),if i>1,fprintf(fid,', ');end;fprintf(fid,'%s',bench.labels{i});end;fprintf(fid,'\nScenarios:\n');for i=1:numel(bench.scenarios),fprintf(fid,'  %d. %s (%s)\n',i,bench.scenarios(i).label,bench.scenarios(i).name);end;fprintf(fid,'Controller benchmark scenarios 1-4 use truth-state feedback; scenarios 5-6 use common EKF output feedback.\n');fprintf(fid,'Monte Carlo isolates matched parametric model mismatch around the nominal reference; deterministic disturbances are evaluated separately.\n');fprintf(fid,'Physical actuator dynamics/rate limits are in the plant. Additional common command slew limiting is disabled; MPC explicit slew constraints are evaluated as a design feature.\n');fprintf(fid,'Matched Monte Carlo perturbations are reused across all controllers.\nMonte Carlo success rates: ');fprintf(fid,'%.2f ',mc.successRate);fprintf(fid,'%%\n');fclose(fid);
end
